mutation {
         orderCreate(
           input: {
             fulfillment: {
               trackingNumbers: [
                 { number: "1234567890", carrierCode: "UPS" },
                 { number: "9876543210", carrierCode: "FedEx" }
               ]
             }
           }
         ) {
           order {
             id
             fulfillments {
               trackingNumbers {
                 number
                 carrierCode
               }
             }
           }
         }
       }
